"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "motion/react";
import { Sparkles, Mic, Volume2 } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AppleIntelligenceRippleProps
  extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  active?: boolean;
  onTrigger?: () => void;
}

export function AppleIntelligenceRipple({
  children,
  active: propActive,
  onTrigger,
  className,
  ...props
}: AppleIntelligenceRippleProps) {
  const [internalActive, setInternalActive] = useState(false);
  const isControlled = propActive !== undefined;
  const isActive = isControlled ? propActive : internalActive;

  const handleToggle = () => {
    const next = !isActive;
    if (!isControlled) setInternalActive(next);
    onTrigger?.();
  };

  return (
    <div
      data-slot="apple-intelligence-ripple"
      className={cn("relative flex items-center justify-center p-8 select-none", className)}
      {...props}
    >
      {/* Outer Iridescent Ripple Layers */}
      <AnimatePresence>
        {isActive ? (
          <>
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{
                opacity: [0.4, 0.9, 0.4],
                scale: [1, 1.05, 1],
                rotate: [0, 180, 360],
              }}
              exit={{ opacity: 0, scale: 0.95 }}
              transition={{
                duration: 6,
                repeat: Infinity,
                ease: "linear",
              }}
              className="pointer-events-none absolute -inset-6 rounded-[36px] bg-gradient-to-tr from-rose-500 via-purple-500 via-sky-400 to-amber-300 opacity-60 blur-2xl"
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.9 }}
              animate={{
                opacity: [0.6, 1, 0.6],
                scale: [1, 1.03, 1],
                rotate: [360, 180, 0],
              }}
              exit={{ opacity: 0, scale: 0.9 }}
              transition={{
                duration: 4,
                repeat: Infinity,
                ease: "linear",
              }}
              className="pointer-events-none absolute -inset-3 rounded-[32px] bg-gradient-to-br from-indigo-500 via-pink-500 to-teal-400 opacity-70 blur-xl"
            />
          </>
        ) : null}
      </AnimatePresence>

      {/* Main Container Card */}
      <motion.div
        animate={{
          scale: isActive ? [1, 1.01, 1] : 1,
        }}
        transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
        className="relative z-10 w-full max-w-md overflow-hidden rounded-3xl border border-white/20 bg-white/90 p-6 shadow-2xl backdrop-blur-2xl dark:border-white/10 dark:bg-neutral-900/90"
      >
        {/* Glow border ring */}
        <div
          className={cn(
            "pointer-events-none absolute inset-0 rounded-3xl transition-opacity duration-500",
            isActive
              ? "ring-2 ring-purple-500/50 shadow-[inset_0_0_20px_rgba(168,85,247,0.3)]"
              : "ring-1 ring-black/5 dark:ring-white/10"
          )}
        />

        {children || (
          <div className="flex flex-col gap-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2.5">
                <div className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-tr from-rose-500 to-indigo-500 text-white shadow-md">
                  <Sparkles className="h-4 w-4" />
                </div>
                <div>
                  <h4 className="text-xs font-bold uppercase tracking-wider text-neutral-900 dark:text-neutral-100">
                    Apple Intelligence
                  </h4>
                  <p className="text-[11px] text-neutral-500">Siri Waveform Assistant</p>
                </div>
              </div>

              <motion.button
                type="button"
                onClick={handleToggle}
                whileHover={{ scale: 1.06 }}
                whileTap={{ scale: 0.94 }}
                className={cn(
                  "flex h-9 w-9 items-center justify-center rounded-full text-white shadow-md transition-colors cursor-pointer",
                  isActive
                    ? "bg-gradient-to-r from-purple-500 to-pink-500"
                    : "bg-neutral-800 hover:bg-neutral-700 dark:bg-neutral-700 dark:hover:bg-neutral-600"
                )}
              >
                {isActive ? <Volume2 className="h-4 w-4 animate-pulse" /> : <Mic className="h-4 w-4" />}
              </motion.button>
            </div>

            <div className="rounded-2xl bg-neutral-100/80 p-4 dark:bg-neutral-800/60">
              <p className="text-xs text-neutral-700 dark:text-neutral-300 leading-relaxed font-medium">
                {isActive
                  ? "Listening... Analyzing screen context and prioritizing urgent notifications with contextual summary."
                  : "Tap the microphone to awaken Apple Intelligence luminous edge-glow and audio reactive ripples."}
              </p>
            </div>
          </div>
        )}
      </motion.div>
    </div>
  );
}
